import java.util.*;

public class Main {
    List<Integer> reorderList(List<Integer> values) {
        List<Integer> result = new ArrayList<>();
        int lo = 0, hi = values.size() - 1;
        int turn = 0;
        while (lo <= hi) {
            if (turn % 2 == 0) {                                                    // alternate: front of the list, then back of the list
                result.add(values.get(lo++));
            } else {
                result.add(values.get(hi--));
            }
            turn++;
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        List<Integer> values = Arrays.asList(1, 2, 3, 4, 5);
        System.out.println(solution.reorderList(values));
    }
}

