#include <bits/stdc++.h>
using namespace std;

vector<int> reorderList(vector<int>& values) {
    vector<int> result;
    int lo = 0, hi = (int)values.size() - 1;
    int turn = 0;
    while (lo <= hi) {
        if (turn % 2 == 0) {                                                       // alternate: front of the list, then back of the list
            result.push_back(values[lo++]);
        } else {
            result.push_back(values[hi--]);
        }
        turn++;
    }
    return result;
}

int main() {
    vector<int> values = {1, 2, 3, 4, 5};
    vector<int> result = reorderList(values);
    for (int v : result) cout << v << " ";
    cout << endl;
    return 0;
}

