import java.util.*;

public class Main {
    ListNode reverse(ListNode head) {
        ListNode prev = null;
        while (head != null) {
            ListNode next = head.next;
            head.next = prev;
            prev = head;
            head = next;
        }
        return prev;
    }

    void reorderList(ListNode head) {
        if (head == null || head.next == null) return;

        ListNode slow = head, fast = head;                                              // phase 1: find the middle (slow/fast pointers)
        while (fast.next != null && fast.next.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        ListNode second = slow.next;                                                       // phase 2: split into two halves, reverse the second
        slow.next = null;
        second = reverse(second);

        ListNode first = head;                                                             // phase 3: weave the two halves together, alternating
        while (second != null) {
            ListNode t1 = first.next, t2 = second.next;
            first.next = second;
            second.next = t1;
            first = t1;
            second = t2;
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode head = new ListNode(1, new ListNode(2, new ListNode(3, new ListNode(4, new ListNode(5)))));
        solution.reorderList(head);
        StringBuilder sb = new StringBuilder();
        ListNode node = head;
        while (node != null) { sb.append(node.val).append(" "); node = node.next; }
        System.out.println(sb.toString().trim());
    }
}

