#include <bits/stdc++.h>
using namespace std;

ListNode* reverse(ListNode* head) {
    ListNode* prev = nullptr;
    while (head) {
        ListNode* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

void reorderList(ListNode* head) {
    if (!head || !head->next) return;

    ListNode *slow = head, *fast = head;                                                    // phase 1: find the middle (slow/fast pointers)
    while (fast->next && fast->next->next) {
        slow = slow->next;
        fast = fast->next->next;
    }

    ListNode* second = slow->next;                                                             // phase 2: split into two halves, reverse the second
    slow->next = nullptr;
    second = reverse(second);

    ListNode* first = head;                                                                     // phase 3: weave the two halves together, alternating
    while (second) {
        ListNode *t1 = first->next, *t2 = second->next;
        first->next = second;
        second->next = t1;
        first = t1;
        second = t2;
    }
}

int main() {
    ListNode* head = new ListNode(1, new ListNode(2, new ListNode(3, new ListNode(4, new ListNode(5)))));
    reorderList(head);
    ListNode* node = head;
    while (node) { cout << node->val << " "; node = node->next; }
    cout << endl;
    return 0;
}
